// Recorrer todos los items que entran al nodo
const resultados = [];

for (const item of $input.all()) {
  const texto = item.json.data || '';
  // Regex para URLs (http, https, www)
  const regexUrl = /(https?:\/\/[^\s]+)|(www\.[^\s]+)/gi;

  // Extraer URLs, si no hay ninguna, el resultado es []
  const urls = texto.match(regexUrl) || [];

  // Por cada URL encontrada, crear un nuevo item con la URL
  for (const url of urls) {
    resultados.push({ json: { url } });
  }
}

// Devolver un array de objetos con las URLs extraídas
return resultados;
